import {form,number as num,select as sel,text,area,field,result,outputText,e,n,error} from '../ui.mjs';
import {age,dateUTC} from '../core.mjs';
import {dateOffset} from '../advanced-core.mjs';
import {restingEnergy,macros,activityCalories,bedtime,dueDate,pregnancyAge} from './calc-core.mjs';
import {need,optional,today,localNow,dayDiff,table,exportCSV,fileResult} from './shared.mjs';
const adultFields=()=>[sel('sex','Equation coefficient',[['male','Male equation (+5)'],['female','Female equation (−161)']],'male'),num('age','Age (years)',30,19,78,1),num('weight','Weight (kg)',70,25,350),num('height','Height (cm)',175,100,250)];
const healthNote='Informational estimates for adults. Not a diagnosis or an individual nutrition prescription.';
export function setupWellness(tool,mount,out){
 const id=tool.id,show=o=>result(out,o);
 if(['feeding-journal','diaper-log'].includes(id))return journal(id,mount,out);
 if(id==='contraction-timer')return contraction(mount,out);
 if(id==='baby-names')return namesTool(mount,out);
 if(id==='pregnancy-announcement')return announcement(mount,out);
 const forms={
 bmr:()=>form(mount,adultFields(),v=>{const r=restingEnergy(+v.weight,+v.height,+v.age,v.sex);need(r>0,'These inputs do not produce a plausible positive resting-energy estimate.');show({label:'Estimated resting energy',value:n(r)+' kcal/day',details:[['Method','Mifflin–St Jeor'],['Equation',`10 × kg + 6.25 × cm − 5 × years ${v.sex==='male'?'+ 5':'− 161'}`]],copy:r.toFixed(2)+' kcal/day',note:healthNote});},{label:'Estimate resting energy',note:'Original equation research included healthy adults aged 19–78. It estimates resting expenditure rather than measuring metabolism.'}),
 tdee:()=>form(mount,[...adultFields(),num('pal','Assumed physical activity level (PAL)',1.55,1.1,2.5,.01)],v=>{const r=restingEnergy(+v.weight,+v.height,+v.age,v.sex);need(r>0,'Check the entered age, height and weight.');show({label:'Estimated total daily expenditure',value:n(r*+v.pal)+' kcal/day',details:[['Resting-energy estimate',n(r)+' kcal/day'],['Entered activity multiplier',v.pal],['Formula','Resting estimate × PAL']],copy:(r*+v.pal).toFixed(2)+' kcal/day',note:healthNote});},{label:'Estimate daily expenditure',note:'PAL is an assumption, not a measured activity score. FAO lifestyle ranges: light 1.40–1.69; moderate 1.70–1.99; vigorous 2.00–2.40.'}),
 'macro-calculator':()=>form(mount,[num('calories','Your calorie budget (kcal)',2000,1,10000),num('carb','Carbohydrate (%)',50,0,100),num('protein','Protein (%)',20,0,100),num('fat','Fat (%)',30,0,100)],v=>{const r=macros(+v.calories,+v.carb,+v.protein,+v.fat);show({label:'Your chosen split',value:v.calories+' kcal',details:[['Carbohydrate',n(r.carb)+' g'],['Protein',n(r.protein)+' g'],['Fat',n(r.fat)+' g'],['Energy factors','Carbohydrate 4, protein 4, fat 9 kcal/g']],copy:`Carbohydrate: ${r.carb.toFixed(1)} g\nProtein: ${r.protein.toFixed(1)} g\nFat: ${r.fat.toFixed(1)} g`,note:'The calorie budget and split are your choices. No ideal diet is inferred.'});},{label:'Convert calories to grams'}),
 'calories-burned':()=>form(mount,[num('met','Entered MET value',6,1,25,.1),num('weight','Body weight (kg)',70,25,350),num('minutes','Duration (minutes)',30,1,1440)],v=>{const gross=activityCalories(+v.met,+v.weight,+v.minutes),net=activityCalories(Math.max(0,+v.met-1),+v.weight,+v.minutes);show({label:'Estimated gross energy',value:n(gross)+' kcal',details:[['Net above assumed rest',n(net)+' kcal'],['Formula','MET × 3.5 × kg ÷ 200 × minutes'],['MET input',v.met]],copy:gross.toFixed(1)+' gross kcal',note:'Gross includes resting expenditure. MET is an entered population-average assumption, not an individual measurement.'});},{label:'Estimate activity energy'}),
 'sleep-planner':()=>form(mount,[text('wake','Wake-up time','07:00','time'),num('hours','Desired time asleep (hours)',8,1,14,.25),num('settle','Time to fall asleep (minutes)',15,0,180,1)],v=>{const r=bedtime(v.wake,+v.hours,+v.settle);show({label:'Get into bed around',value:r.time,details:[['Day',r.previous?'Previous evening/day':'Same day'],['Desired sleep',v.hours+' hours'],['Settling time',v.settle+' minutes']],copy:r.time+(r.previous?' the previous day':''),note:'This works backward from your chosen duration. It does not predict exact sleep stages.'});},{label:'Plan bedtime'}),
 'due-date':()=>form(mount,[text('lmp','First day of last period',dateOffset(today(),-84),'date'),num('cycle','Assumed regular cycle length (days)',28,21,45,1)],v=>{const d=dueDate(v.lmp,+v.cycle);show({label:'Estimated due date',value:d,details:[['LMP input',v.lmp],['Assumption',`280 days + (${v.cycle} − 28) days from LMP`]],copy:d,note:'An estimate, not confirmation of pregnancy. Use your maternity team’s confirmed dating for care.'});},{label:'Estimate due date'}),
 'pregnancy-weeks':()=>form(mount,[text('edd','Estimated or clinician-provided due date',dateOffset(today(),196),'date'),text('asof','Reference date',today(),'date')],v=>{const r=pregnancyAge(v.edd,v.asof);show({label:'Estimated gestational age',value:r.weeks+' weeks '+r.extra+' days',details:[['Trimester',r.trimester],['Due date',v.edd],['Reference date',v.asof],['Method','280 days minus days remaining to EDD']],copy:r.weeks+' weeks '+r.extra+' days',note:'Trimester boundaries: first through 13w6d; second 14w0d–27w6d; third from 28w0d. Dating depends on the due date entered.'});},{label:'Calculate weeks & trimester'}),
 'period-calendar':()=>form(mount,[text('last','First day of last period',today(),'date'),num('cycle','Assumed cycle length (days)',28,15,60,1),num('count','Future cycles to show',6,1,12,1)],v=>{const rows=Array.from({length:+v.count},(_,i)=>[i+1,dateOffset(v.last,+v.cycle*(i+1))]);show({html:table(['Cycle','Estimated start'],rows),copy:rows.map(r=>r.join(': ')).join('\n'),note:'Projections assume the same cycle length each time. They are not contraception or a pregnancy test.'});exportCSV(out,rows.map(([cycle,date])=>({cycle,estimated_start:date})),'nepocore-period-calendar.csv');},{label:'Project cycle dates'}),
 'ovulation-window':()=>form(mount,[text('last','First day of last period',today(),'date'),num('cycle','Assumed regular cycle length (days)',28,21,45,1)],v=>{const next=dateOffset(v.last,+v.cycle),early=dateOffset(next,-16),late=dateOffset(next,-10);show({label:'Approximate ovulation interval',value:early+' to '+late,details:[['Midpoint estimate',dateOffset(next,-14)],['Predicted next period',next],['Assumption','Around 10–16 days before next period']],copy:early+' to '+late,note:'This is an approximate calendar interval, not the complete fertile window. It cannot confirm ovulation and is not reliable contraception.'});},{label:'Show estimated interval'}),
 'baby-age':()=>form(mount,[text('birth','Birth date',dateOffset(today(),-100),'date'),text('asof','Reference date',today(),'date')],v=>{const r=age(v.birth,v.asof);show({label:'Calendar age',value:`${r.years} years ${r.months} months ${r.days} days`,details:[['Completed calendar months',r.years*12+r.months],['Weeks and days',Math.floor(r.totalDays/7)+' weeks '+r.totalDays%7+' days'],['Total days',r.totalDays]],copy:`${r.years} years ${r.months} months ${r.days} days`,note:'Calendar age only. This does not assess development or automatically correct for prematurity.'});},{label:'Calculate calendar age'})
 };
 need(forms[id],'This wellness tool is unavailable.');forms[id]();
}
function journal(id,mount,out){const feeding=id==='feeding-journal';let rows=[];mount.innerHTML='<h2>A private session journal</h2><p class="form-note">Entries stay in this page session. Export before leaving; no automatic saving.</p><form><div class="form-grid">'+[text('time','Date & time',localNow(),'datetime-local'),sel('type',feeding?'Feeding type':'Change type',feeding?['Bottle','Breastfeed','Other']:['Wet','Dirty','Both','Other'],feeding?'Bottle':'Wet'),...(feeding?[optional(num('amount','Amount (mL, optional)','',0,2000))]:[]),optional(area('note','Notes',''))].map(field).join('')+'</div><div class="form-actions"><button class="btn primary" type="submit">Add entry</button><button class="btn secondary" type="button" data-clear>Clear journal</button></div><div class="form-error"></div></form>';const f=mount.querySelector('form');function render(){if(!rows.length){out.innerHTML='<div class="result-placeholder">Add your first entry to begin.</div>';return;}result(out,{html:table(['Time','Type',...(feeding?['Amount (mL)']:[]),'Notes','Remove'],rows.map((r,i)=>[r.time.replace('T',' '),r.type,...(feeding?[r.amount||'—']:[]),r.note,i+1])),copy:rows.map(r=>Object.values(r).join(' · ')).join('\n')});out.querySelectorAll('tbody tr').forEach((tr,i)=>{const b=document.createElement('button');b.className='btn secondary small';b.textContent='Remove';b.setAttribute('aria-label','Remove entry '+(i+1));b.onclick=()=>{rows.splice(i,1);render();};tr.lastElementChild.replaceChildren(b);});exportCSV(out,rows,'nepocore-'+id+'.csv');}f.onsubmit=ev=>{ev.preventDefault();if(!f.reportValidity())return;try{need(rows.length<500,'Export and clear the journal after 500 entries.');const v=Object.fromEntries(new FormData(f));rows.push(v);f.elements.note.value='';render();}catch(ex){error(f.querySelector('.form-error'),ex.message);}};mount.querySelector('[data-clear]').onclick=()=>{rows=[];render();};render();}
function contraction(mount,out){let start=null,timer=null,rows=[];mount.innerHTML='<h2>Time and record</h2><p class="form-note">A timing log cannot assess labour. Follow your maternity team’s advice; contact them if concerned.</p><div class="large-timer" data-elapsed>00:00</div><div class="form-actions"><button class="btn primary" data-start>Start contraction</button><button class="btn secondary" data-end disabled>End contraction</button><button class="btn secondary" data-reset>Clear log</button></div>';const begin=mount.querySelector('[data-start]'),end=mount.querySelector('[data-end]'),display=mount.querySelector('[data-elapsed]');function render(){result(out,{label:'Completed contractions',value:rows.length,html:rows.length?table(['Started','Duration (sec)','Start-to-start (sec)'],rows.map(r=>[new Date(r.start).toLocaleTimeString(),r.duration.toFixed(1),r.interval===null?'First':r.interval.toFixed(1)])):'<p class="form-note">Tap Start when a contraction begins, then End when it finishes.</p>',copy:JSON.stringify(rows,null,2)});if(rows.length)exportCSV(out,rows,'nepocore-contractions.csv');}begin.onclick=()=>{start=Date.now();begin.disabled=true;end.disabled=false;timer=setInterval(()=>{const seconds=(Date.now()-start)/1000;display.textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(Math.floor(seconds%60)).padStart(2,'0');},200);};end.onclick=()=>{if(start===null)return;const last=rows.at(-1);rows.push({start,end:Date.now(),duration:(Date.now()-start)/1000,interval:last?(start-last.start)/1000:null});start=null;clearInterval(timer);begin.disabled=false;end.disabled=true;display.textContent='00:00';render();};mount.querySelector('[data-reset]').onclick=()=>{clearInterval(timer);start=null;rows=[];begin.disabled=false;end.disabled=true;display.textContent='00:00';render();};render();return()=>clearInterval(timer);}
function namesTool(mount,out){const names=['Aarya','Aarav','Aarohi','Aditi','Anaya','Anish','Anvi','Arjun','Asha','Avni','Bina','Diya','Esha','Ishan','Jiya','Kabir','Kiran','Maya','Meera','Milan','Nabin','Naira','Neha','Nila','Nirav','Pranav','Riya','Rohan','Saanvi','Samir','Sara','Sia','Tara','Veda','Vihaan','Zara'];let chosen=[];mount.innerHTML='<h2>A little list of possibilities</h2><label class="field"><span>Filter names</span><input data-filter type="search" placeholder="Type a name or first letter"></label><div class="name-choices"></div><form class="inline-form"><label class="field"><span>Add your own name</span><input name="name" required maxlength="70"></label><button class="btn secondary" type="submit">Add name</button></form>';function render(){const query=mount.querySelector('[data-filter]').value.toLowerCase(),box=mount.querySelector('.name-choices');box.replaceChildren();names.filter(x=>x.toLowerCase().includes(query)).forEach(name=>{const b=document.createElement('button');b.className='choice-pill';b.textContent=name+(chosen.includes(name)?' ✓':' +');b.onclick=()=>{if(chosen.includes(name))chosen=chosen.filter(x=>x!==name);else chosen.push(name);render();};box.append(b);});outputText(out,chosen.length?chosen.join('\n'):'Your shortlist is empty. Add a name to begin.',[['Shortlisted',chosen.length]]);if(chosen.length)exportCSV(out,chosen.map(name=>({name})),'nepocore-baby-name-shortlist.csv');}mount.querySelector('[data-filter]').oninput=render;mount.querySelector('form').onsubmit=ev=>{ev.preventDefault();const input=ev.currentTarget.elements.name,v=input.value.trim();if(!v)return;if(!names.includes(v))names.push(v);if(!chosen.includes(v))chosen.push(v);input.value='';render();};render();}
function announcement(mount,out){let release=()=>{},disposed=false;form(mount,[text('headline','Headline','A little love is on the way','text',true),text('family','Family / names','Our next chapter'),text('arrival','Arrival text','Arriving soon'),text('color','Accent color','#c78592','color')],async v=>{const {canvas,canvasBlob}=await import('../media.mjs');const c=canvas(900,1200),x=c.getContext('2d');x.fillStyle='#fff8f2';x.fillRect(0,0,900,1200);x.fillStyle=v.color;x.globalAlpha=.15;x.beginPath();x.arc(450,420,320,0,Math.PI*2);x.fill();x.globalAlpha=1;x.fillStyle=v.color;x.font='100px Georgia';x.textAlign='center';x.fillText('♡',450,330);x.fillStyle='#343c3a';x.font='46px Georgia';const words=v.headline.split(/\s+/);let line='',y=500;for(const word of words){if(x.measureText(line+word).width>730&&line){x.fillText(line.trim(),450,y);line=word+' ';y+=65;}else line+=word+' ';}x.fillText(line.trim(),450,y);x.font='26px sans-serif';x.fillText(v.family.slice(0,65),450,800,760);x.font='24px sans-serif';x.fillStyle=v.color;x.fillText(v.arrival.slice(0,65),450,885,760);x.font='16px sans-serif';x.fillStyle='#8d9690';x.fillText('Made with Nepocore',450,1140);const blob=await canvasBlob(c);if(disposed)return;release();release=fileResult(out,blob,'nepocore-announcement.png',{image:true,details:[['Size','900 × 1200 px']]});},{label:'Create announcement'});return()=>{disposed=true;release();};}
